import json
import time

import boto3


def write_correlated_logs(payloads, correlation_id, config=None):
    config = config or {}
    client = boto3.client("logs", region_name=config.get("region"))
    log_events = []
    for payload in payloads:
        log_events.append({
            "timestamp": int(payload.get("timestamp_ms", time.time() * 1000)),
            "message": json.dumps(payload["event"]),
            "correlation_id": correlation_id,
        })
    response = client.put_log_events(
        logGroupName=config["log_group"],
        logStreamName=config["log_stream"],
        logEvents=log_events,
    )
    if response.get("rejectedLogEventsInfo") or response.get("rejectedEntityInfo"):
        raise RuntimeError("The logging service rejected the event")
    return {"submitted": True}

import os
import boto3


def get_observability_client():
    config = {
        "region": os.getenv("AWS_REGION"),
        "log_group": os.getenv("LOG_GROUP_NAME"),
        "log_stream": os.getenv("LOG_STREAM_NAME"),
    }
    return boto3.client("logs", region_name=config["region"]), config

from typing import Dict, List


def normalize_log_event(event: Dict) -> Dict:
    return {
        "timestamp_ms": int(event.get("timestamp_ms", time.time() * 1000)),
        "event": event.get("event", {}),
    }


def parse_log_response(response: Dict) -> List[Dict]:
    return response.get("events", [])

import re


def check_log_text_safety(log_text):
    unsafe_patterns = [
        r"password",
        r"secret",
        r"api_key",
    ]
    for pattern in unsafe_patterns:
        if re.search(pattern, log_text, re.IGNORECASE):
            return False
    return True

from sentence_transformers import SentenceTransformer


def embed_log_message(message):
    model = SentenceTransformer('all-MiniLM-L6-v2')
    embedding = model.encode(message)
    return embedding.tolist()
